cat <<'EOF' > src/main.rs
use clap::{Arg, ArgAction, Command};
use git2::{BranchType, Config, Oid, Repository};
use glob::Pattern;
use std::collections::{BTreeMap, HashSet};
use std::io::{self, IsTerminal, Write};
use std::process::{exit, Command as SystemCommand};

#[derive(Debug, Clone, PartialEq, Eq)]
enum DeleteRange {
    MergedLocal,
    MergedRemote(String), // remote name or "*"
    Stray,
    Diverged(String),     // remote name or "*"
    Local,
    Remote(String),       // remote name or "*"
}

fn parse_delete_ranges(delete_str: &str) -> Result<Vec<DeleteRange>, String> {
    let mut ranges = Vec::new();
    for token in delete_str.split(',') {
        let token = token.trim();
        if token.is_empty() {
            continue;
        }
        if token == "merged-local" {
            ranges.push(DeleteRange::MergedLocal);
        } else if token == "stray" {
            ranges.push(DeleteRange::Stray);
        } else if token == "local" {
            ranges.push(DeleteRange::Local);
        } else if let Some(remote) = token.strip_prefix("merged-remote:") {
            if remote.is_empty() {
                return Err(token.to_string());
            }
            ranges.push(DeleteRange::MergedRemote(remote.to_string()));
        } else if let Some(remote) = token.strip_prefix("diverged:") {
            if remote.is_empty() {
                return Err(token.to_string());
            }
            ranges.push(DeleteRange::Diverged(remote.to_string()));
        } else if let Some(remote) = token.strip_prefix("remote:") {
            if remote.is_empty() {
                return Err(token.to_string());
            }
            ranges.push(DeleteRange::Remote(remote.to_string()));
        } else if let Some(remote) = token.strip_prefix("merged:") {
            if remote.is_empty() {
                return Err(token.to_string());
            }
            ranges.push(DeleteRange::MergedLocal);
            ranges.push(DeleteRange::MergedRemote(remote.to_string()));
        } else {
            return Err(token.to_string());
        }
    }
    Ok(ranges)
}

fn matches_remote(range_remote: &str, target_remote: &str) -> bool {
    range_remote == "*" || range_remote == target_remote
}

fn get_config_string(config: &Config, key: &str) -> Option<String> {
    config.get_string(key).ok()
}

fn get_config_bool(config: &Config, key: &str) -> Option<bool> {
    config.get_bool(key).ok()
}

fn get_config_u64(config: &Config, key: &str) -> Option<u64> {
    config.get_i64(key).ok().map(|v| v as u64)
}

fn is_merged(repo: &Repository, commit: Oid, base_commits: &[Oid]) -> bool {
    base_commits.iter().any(|&base| commit == base || repo.graph_descendant_of(base, commit).unwrap_or(false))
}

fn main() {
    let cmd = Command::new("git-trim")
        .version("0.4.4")
        .about("Automatically trims your tracking branches whose upstream branches are merged or stray.")
        .long_about("Automatically trims your tracking branches whose upstream branches are merged or stray.\n`git-trim` is a missing companion to the `git fetch --prune` and a proper, safer, faster alternative to your `<bash oneliner HERE>`.")
        .arg(
            Arg::new("bases")
                .short('b')
                .long("bases")
                .value_name("BASES")
                .help("Comma separated multiple names of branches. All the other branches are compared with the upstream branches of those branches. [default: branches that tracks `git symbolic-ref refs/remotes/*/HEAD`] [config: trim.bases]")
                .long_help("Comma separated multiple names of branches. All the other branches are compared with the upstream branches of those branches. [default: branches that tracks `git symbolic-ref refs/remotes/*/HEAD`] [config: trim.bases]\n\nThe default value is a branch that tracks `git symbolic-ref refs/remotes/*/HEAD`. They might not be reflected correctly when the HEAD branch of your remote repository is changed. You can see the changed HEAD branch name with `git remote show <remote>` and apply it to your local repository with `git remote set-head <remote> --auto`.")
        )
        .arg(
            Arg::new("protected")
                .short('p')
                .long("protected")
                .value_name("PROTECTED")
                .help("Comma separated multiple glob patterns (e.g. `release-*`, `feature/*`) of branches that should never be deleted. [config: trim.protected]")
        )
        .arg(
            Arg::new("no-update")
                .long("no-update")
                .action(ArgAction::SetTrue)
                .help("Do not update remotes [config: trim.update]")
        )
        .arg(
            Arg::new("update-interval")
                .long("update-interval")
                .value_name("UPDATE_INTERVAL")
                .help("Prevents too frequent updates. Seconds between updates in seconds. 0 to disable. [default: 5] [config: trim.updateInterval]")
        )
        .arg(
            Arg::new("no-confirm")
                .long("no-confirm")
                .action(ArgAction::SetTrue)
                .help("Do not ask confirm [config: trim.confirm]")
        )
        .arg(
            Arg::new("no-detach")
                .long("no-detach")
                .action(ArgAction::SetTrue)
                .help("Do not detach when HEAD is about to be deleted [config: trim.detach]")
        )
        .arg(
            Arg::new("delete")
                .short('d')
                .long("delete")
                .value_name("DELETE")
                .help("Comma separated values of `<delete range>[:<remote name>]`. Delete range is one of the `merged, merged-local, merged-remote, stray, diverged, local, remote`. `:<remote name>` is only necessary to a `<delete range>` when the range is applied to remote branches. You can use `*` as `<remote name>` to delete a range of branches from all remotes. [default : `merged:origin`] [config: trim.delete]")
                .long_help("Comma separated values of `<delete range>[:<remote name>]`. Delete range is one of the `merged, merged-local, merged-remote, stray, diverged, local, remote`. `:<remote name>` is only necessary to a `<delete range>` when the range is applied to remote branches. You can use `*` as `<remote name>` to delete a range of branches from all remotes. [default : `merged:origin`] [config: trim.delete]\n\n`merged` implies `merged-local,merged-remote`.\n\n`merged-local` will delete merged tracking local branches. `merged-remote:<remote>` will delete merged upstream branches from `<remote>`. `stray` will delete tracking local branches, which is not merged, but the upstream is gone. `diverged:<remote>` will delete merged tracking local branches, and their upstreams from `<remote>` even if the upstreams are not merged and diverged from local ones. `local` will delete non-tracking merged local branches. `remote:<remote>` will delete non-upstream merged remote tracking branches. Use with caution when you are using other than `merged`. It might lose changes, and even nuke repositories.")
        )
        .arg(
            Arg::new("dry-run")
                .long("dry-run")
                .action(ArgAction::SetTrue)
                .help("Do not delete branches, show what branches will be deleted")
        );

    let matches = cmd.get_matches();

    let repo = match Repository::discover(".") {
        Ok(r) => r,
        Err(e) => {
            eprintln!("Error: {}", e);
            exit(1);
        }
    };

    let git_config = repo.config().ok();

    let bases_opt = matches
        .get_one::<String>("bases")
        .cloned()
        .or_else(|| git_config.as_ref().and_then(|c| get_config_string(c, "trim.bases")));

    let protected_opt = matches
        .get_one::<String>("protected")
        .cloned()
        .or_else(|| git_config.as_ref().and_then(|c| get_config_string(c, "trim.protected")));

    let update = if matches.get_flag("no-update") {
        false
    } else {
        git_config
            .as_ref()
            .and_then(|c| get_config_bool(c, "trim.update"))
            .unwrap_or(true)
    };

    let _update_interval = matches
        .get_one::<String>("update-interval")
        .and_then(|s| s.parse::<u64>().ok())
        .or_else(|| git_config.as_ref().and_then(|c| get_config_u64(c, "trim.updateInterval")))
        .unwrap_or(5);

    let confirm = if matches.get_flag("no-confirm") {
        false
    } else {
        git_config
            .as_ref()
            .and_then(|c| get_config_bool(c, "trim.confirm"))
            .unwrap_or(true)
    };

    let detach = if matches.get_flag("no-detach") {
        false
    } else {
        git_config
            .as_ref()
            .and_then(|c| get_config_bool(c, "trim.detach"))
            .unwrap_or(true)
    };

    let delete_str = matches
        .get_one::<String>("delete")
        .cloned()
        .or_else(|| git_config.as_ref().and_then(|c| get_config_string(c, "trim.delete")))
        .unwrap_or_else(|| "merged:origin".to_string());

    let dry_run = matches.get_flag("dry-run");

    let delete_ranges = match parse_delete_ranges(&delete_str) {
        Ok(r) => r,
        Err(bad_val) => {
            eprintln!("error: invalid value '{}' for '--delete <DELETE>': Invalid delete range format `{}`\n\nFor more information, try '--help'.", bad_val, bad_val);
            exit(2);
        }
    };

    let remotes_sa = match repo.remotes() {
        Ok(r) => r,
        Err(e) => {
            eprintln!("Error: {}", e);
            exit(1);
        }
    };

    let mut remote_names: Vec<String> = Vec::new();
    for r in &remotes_sa {
        if let Some(name) = r {
            remote_names.push(name.to_string());
        }
    }

    if remote_names.is_empty() {
        eprintln!("Error: git-trim requires at least one remote");
        exit(1);
    }

    if update && !dry_run {
        for remote_name in &remote_names {
            println!("Fetching {}", remote_name);
            let _ = SystemCommand::new("git")
                .args(&["fetch", "--prune", remote_name])
                .status();
        }
    }

    let mut base_branch_names: Vec<String> = Vec::new();
    if let Some(bases_str) = bases_opt {
        for b in bases_str.split(',') {
            let b = b.trim();
            if !b.is_empty() {
                base_branch_names.push(b.to_string());
            }
        }
    } else {
        for remote_name in &remote_names {
            let symref_name = format!("refs/remotes/{}/HEAD", remote_name);
            match repo.find_reference(&symref_name) {
                Ok(reference) => {
                    if let Some(target) = reference.symbolic_target() {
                        let prefix = format!("refs/remotes/{}/", remote_name);
                        if let Some(branch_name) = target.strip_prefix(&prefix) {
                            base_branch_names.push(branch_name.to_string());
                        }
                    }
                }
                Err(_) => {
                    eprintln!(
                        "I can't detect base branch! Try following any resolution:\n\
                        You also can set bases manually with any of following commands:\n\
                         * `git remote set-head {} --auto` will help `git-trim` to automatically\n   \
                           detect the base branch.\n   \
                           If you see `origin/HEAD set to <base branch>` in the output of the previous\n   \
                           command, then `git branch --set-upstream {}/<base branch> <base branch>`\n   \
                           to set an upstream branch for <base branch> if exists.\n \
                         * `git config trim.bases develop,master` for a repository.\n \
                         * `git config --global trim.bases develop,master` to set globally.\n \
                         * `git trim --bases develop,master` to set temporarily.\n\
                        Error: No base branch is found!",
                        remote_name, remote_name
                    );
                    exit(1);
                }
            }
        }
    }

    let mut base_commits: Vec<Oid> = Vec::new();
    let mut base_local_names: HashSet<String> = HashSet::new();
    let mut base_remote_names: HashSet<String> = HashSet::new();

    for base_name in &base_branch_names {
        if let Ok(branch) = repo.find_branch(base_name, BranchType::Local) {
            if let Some(target) = branch.get().target() {
                base_commits.push(target);
                base_local_names.insert(base_name.clone());
            }
        }
        for remote_name in &remote_names {
            let remote_ref = format!("{}/{}", remote_name, base_name);
            if let Ok(branch) = repo.find_branch(&remote_ref, BranchType::Remote) {
                if let Some(target) = branch.get().target() {
                    base_commits.push(target);
                    base_remote_names.insert(remote_ref.clone());
                }
            }
        }
    }

    let mut protected_patterns = Vec::new();
    if let Some(p_str) = protected_opt {
        for p in p_str.split(',') {
            let p = p.trim();
            if !p.is_empty() {
                if let Ok(pat) = Pattern::new(p) {
                    protected_patterns.push((p.to_string(), pat));
                }
            }
        }
    }

    let head_branch_name: Option<String> = repo.head().ok().and_then(|head_ref| {
        if head_ref.is_branch() {
            head_ref.shorthand().map(|s| s.to_string())
        } else {
            None
        }
    });

    // Data structures for output and deletion
    let mut remaining_local: BTreeMap<String, String> = BTreeMap::new();
    let mut remaining_remote: BTreeMap<String, String> = BTreeMap::new();

    let mut delete_merged_local: Vec<(String, bool)> = Vec::new(); // (branch_name, non_tracking)
    let mut delete_merged_remote: Vec<(String, String, bool)> = Vec::new(); // (remote, branch, non_upstream)
    let mut delete_stray_local: Vec<String> = Vec::new();
    let mut delete_diverged_remote: Vec<(String, String)> = Vec::new();

    let mut needs_fn1 = false;
    let mut needs_fn2 = false;
    let mut needs_fn3 = false;
    let mut fn3_remote_str = String::from("remote:*");

    let local_branches = repo.branches(Some(BranchType::Local)).unwrap();
    let mut local_tracking_upstreams: HashSet<String> = HashSet::new();

    for item in local_branches {
        let (branch, _) = item.unwrap();
        let name = branch.name().unwrap().unwrap().to_string();
        let commit_id = match branch.get().target() {
            Some(c) => c,
            None => continue,
        };

        let upstream_ref_name = branch.upstream().ok().and_then(|u| u.name().ok().flatten().map(|s| s.to_string()));
        if let Some(ref u_name) = upstream_ref_name {
            local_tracking_upstreams.insert(u_name.clone());
        }

        let is_base = base_local_names.contains(&name);

        let prot_match = protected_patterns.iter().find(|(_, pat)| pat.matches(&name));

        let is_head = head_branch_name.as_deref() == Some(&name);

        if is_base {
            let mut tag = String::from("[base]");
            if upstream_ref_name.is_none() {
                // local base
            } else {
                let u_exists = branch.upstream().is_ok();
                if !u_exists {
                    tag = String::from("[stray, but: base]");
                }
            }
            remaining_local.insert(name, tag);
            continue;
        }

        if let Some((pat_str, _)) = prot_match {
            let tag = format!("[merged, but: protected by a pattern `{}`]", pat_str);
            remaining_local.insert(name, tag);
            continue;
        }

        if is_head && !detach {
            remaining_local.insert(name, String::from("[merged, but: HEAD]"));
            continue;
        }

        if let Some(ref u_name) = upstream_ref_name {
            // Has upstream
            let u_branch = branch.upstream();
            if let Ok(u_branch) = u_branch {
                let u_commit_id = u_branch.get().target().unwrap();
                let remote_name = u_name.split('/').next().unwrap_or("origin");

                if commit_id == u_commit_id {
                    let merged = is_merged(&repo, commit_id, &base_commits);
                    if merged {
                        let has_range = delete_ranges.contains(&DeleteRange::MergedLocal);
                        if has_range {
                            delete_merged_local.push((name, false));
                        } else {
                            remaining_local.insert(name, String::from("[merged, but: delete range `merged-local` was not given]"));
                            needs_fn1 = true;
                        }
                    } else {
                        remaining_local.insert(name, String::new());
                    }
                } else {
                    // Diverged or different
                    let l_merged = is_merged(&repo, commit_id, &base_commits);
                    let u_merged = is_merged(&repo, u_commit_id, &base_commits);
                    if l_merged && !u_merged {
                        let has_range = delete_ranges.iter().any(|r| match r {
                            DeleteRange::Diverged(r_rem) => matches_remote(r_rem, remote_name),
                            _ => false,
                        });
                        if has_range {
                            delete_merged_local.push((name, false));
                        } else {
                            remaining_local.insert(
                                name,
                                format!(
                                    "[diverged with refs/remotes/{}, but: delete range `diverged:{}` was not given]",
                                    u_name, remote_name
                                ),
                            );
                        }
                    } else if l_merged {
                        let has_range = delete_ranges.contains(&DeleteRange::MergedLocal);
                        if has_range {
                            delete_merged_local.push((name, false));
                        } else {
                            remaining_local.insert(name, String::from("[merged, but: delete range `merged-local` was not given]"));
                            needs_fn1 = true;
                        }
                    } else {
                        remaining_local.insert(name, String::new());
                    }
                }
            } else {
                // Upstream deleted -> Stray
                let l_merged = is_merged(&repo, commit_id, &base_commits);
                if l_merged {
                    let has_range = delete_ranges.contains(&DeleteRange::MergedLocal);
                    if has_range {
                        delete_merged_local.push((name, false));
                    } else {
                        remaining_local.insert(name, String::from("[merged, but: delete range `merged-local` was not given]"));
                        needs_fn1 = true;
                    }
                } else {
                    let has_range = delete_ranges.contains(&DeleteRange::Stray);
                    if has_range {
                        delete_stray_local.push(name);
                    } else {
                        remaining_local.insert(name, String::from("[stray, but: delete range `stray` was not given]"));
                    }
                }
            }
        } else {
            // Non-tracking local branch
            let l_merged = is_merged(&repo, commit_id, &base_commits);
            if l_merged {
                let has_range = delete_ranges.contains(&DeleteRange::Local);
                if has_range {
                    delete_merged_local.push((name, true));
                } else {
                    remaining_local.insert(name, String::from("*2"));
                    needs_fn2 = true;
                }
            } else {
                remaining_local.insert(name, String::from("*2"));
                needs_fn2 = true;
            }
        }
    }

    let remote_branches = repo.branches(Some(BranchType::Remote)).unwrap();

    for item in remote_branches {
        let (branch, _) = item.unwrap();
        let name = branch.name().unwrap().unwrap().to_string();
        if name.ends_with("/HEAD") {
            continue;
        }
        let commit_id = match branch.get().target() {
            Some(c) => c,
            None => continue,
        };
        let parts: Vec<&str> = name.splitn(2, '/').collect();
        let remote_name = parts[0];
        let remote_branch_name = parts.get(1).unwrap_or(&"");

        let is_base = base_remote_names.contains(&name);
        if is_base {
            remaining_remote.insert(name, String::from("[base]"));
            continue;
        }

        let is_upstream = local_tracking_upstreams.contains(&name);

        if is_upstream {
            let u_merged = is_merged(&repo, commit_id, &base_commits);
            if u_merged {
                let has_range = delete_ranges.iter().any(|r| match r {
                    DeleteRange::MergedRemote(r_rem) => matches_remote(r_rem, remote_name),
                    _ => false,
                });
                if has_range {
                    delete_merged_remote.push((remote_name.to_string(), remote_branch_name.to_string(), false));
                } else {
                    remaining_remote.insert(
                        name,
                        format!("[merged, but: delete range `merged-remote:{}` was not given]", remote_name),
                    );
                    needs_fn1 = true;
                }
            } else {
                // Check if diverged
                let mut is_div = false;
                let mut local_ref_name = String::new();
                for item_loc in repo.branches(Some(BranchType::Local)).unwrap() {
                    let (loc_b, _) = item_loc.unwrap();
                    if let Ok(u) = loc_b.upstream() {
                        if u.name().unwrap().unwrap() == name {
                            let loc_commit = loc_b.get().target().unwrap();
                            if is_merged(&repo, loc_commit, &base_commits) && !u_merged {
                                is_div = true;
                                local_ref_name = loc_b.name().unwrap().unwrap().to_string();
                                break;
                            }
                        }
                    }
                }

                if is_div {
                    let has_range = delete_ranges.iter().any(|r| match r {
                        DeleteRange::Diverged(r_rem) => matches_remote(r_rem, remote_name),
                        _ => false,
                    });
                    if has_range {
                        delete_diverged_remote.push((remote_name.to_string(), remote_branch_name.to_string()));
                    } else {
                        remaining_remote.insert(
                            name,
                            format!(
                                "[diverged with refs/heads/{}, but: delete range `diverged:{}` was not given]",
                                local_ref_name, remote_name
                            ),
                        );
                    }
                } else {
                    remaining_remote.insert(name, String::new());
                }
            }
        } else {
            // Non-upstream remote ref
            let u_merged = is_merged(&repo, commit_id, &base_commits);
            if u_merged {
                let has_range = delete_ranges.iter().any(|r| match r {
                    DeleteRange::Remote(r_rem) => matches_remote(r_rem, remote_name),
                    _ => false,
                });
                if has_range {
                    delete_merged_remote.push((remote_name.to_string(), remote_branch_name.to_string(), true));
                } else {
                    remaining_remote.insert(name, String::from("*3"));
                    needs_fn3 = true;
                    if delete_ranges.iter().any(|r| match r {
                        DeleteRange::MergedRemote(r_rem) => r_rem == "*",
                        _ => false,
                    }) {
                        fn3_remote_str = String::from("remote:*");
                    } else {
                        fn3_remote_str = format!("remote:{}", remote_name);
                    }
                }
            } else {
                remaining_remote.insert(name, String::from("*3"));
                needs_fn3 = true;
            }
        }
    }

    let has_deletions = !delete_merged_local.is_empty()
        || !delete_merged_remote.is_empty()
        || !delete_stray_local.is_empty()
        || !delete_diverged_remote.is_empty();

    println!();
    println!("Branches that will remain:");
    println!("  local branches:");
    for (name, tag) in &remaining_local {
